import math

def critical_bond_dimension(k: int, N: int, b: int) -> int:
    target = k ** N
    hi = 2
    while hi ** b < target:
        hi *= 2
    lo = 1
    while lo < hi:
        mid = (lo + hi) // 2
        if mid ** b >= target:
            hi = mid
        else:
            lo = mid + 1
    return lo

def encoding_exists(k, N, b, D): return D ** b >= k ** N

k, b = 2, 4
