    Dc = critical_bond_dimension(k, N, b)
    print(f'N={N:2d} bulk={k**N:5d} D_c={Dc} '
          f'below={encoding_exists(k,N,b,Dc-1)} at={encoding_exists(k,N,b,Dc)}')

