def critical_bond_dimension(k: int, N: int, b: int) -> int:
    """Least D with D**b >= k**N = ceil((k**N)**(1/b)) = D_c(N)."""
    target = k ** N
    hi = 2
    while hi ** b < target:
        hi *= 2
    lo = 1
    while lo < hi:
        mid = (lo + hi) // 2
        if mid ** b >= target:
            hi = mid
        else:
            lo = mid + 1
    return lo

def encoding_exists(k: int, N: int, b: int, D: int) -> bool:
    """True iff a faithful injection Fin(k**N) -> Fin(D**b) exists."""
    return D ** b >= k ** N

import math

def fusion_count(n: int) -> int:
    if n == 0:
        return 1
    if n == 1:
        return 2
    a, b = 1, 2
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def area_law_gap(n: int) -> tuple[int, int, float]:
    """Return (dimension, strict gap 2^n - dim, entanglement density)."""
    dim = fusion_count(n)
    gap = 2 ** n - dim
    density = math.log(dim) / n if n > 0 else 0.0
    return dim, gap, density

